DO $$ 
DECLARE 
    user_record RECORD;
    restaurant_record RECORD;
    review_texts TEXT[] := ARRAY[
        'Отличное место! Все очень понравилось.',
        'Хорошее обслуживание, но еда могла бы быть лучше.',
        'Приятная атмосфера, но слишком долго ждали заказ.',
        'Очень вкусная еда! Обязательно вернусь.',
        'Не понравилось. Ожидал большего.',
        'Очень уютно, но не хватило разнообразия в меню.',
        'Лучший ресторан в городе!',
        'Хорошее соотношение цены и качества.',
        'Еда была на высшем уровне!',
        'Неудачный опыт, к сожалению.'
    ];
    random_review TEXT;
    random_rating INT;
BEGIN
    FOR user_record IN
        SELECT id FROM users
    LOOP
        FOR restaurant_record IN
            SELECT id FROM restaurants
        LOOP
            random_review := review_texts[(random() * array_length(review_texts, 1) + 1)::int];
            random_rating := (floor(random() * 4) + 2)::int; 
            VALUES (
                uuid_generate_v4(), 
                user_record.id,     
                restaurant_record.id, 
                random_review,      
                random_rating,      
                NOW()               
            );
        END LOOP;
    END LOOP;
END $$;



	








































































CREATE OR REPLACE FUNCTION update_restaurant_rating()
RETURNS TRIGGER AS $$
BEGIN
    UPDATE restaurants
    SET 
        rating = ROUND(
            COALESCE((rating * rating_count + NEW.rating) / (rating_count + 1), NEW.rating)::numeric,1)::float,
        rating_count = COALESCE(rating_count, 0) + 1
    WHERE id = NEW.restaurant_id;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER after_review_insert
AFTER INSERT ON reviews
FOR EACH ROW
EXECUTE FUNCTION update_restaurant_rating();

CREATE TEXT SEARCH DICTIONARY russian_ispell (
    TEMPLATE = ispell,
    DictFile = russian,
    AffFile = russian,
    StopWords = russian
);

-- Создание конфигурации для русского языка
CREATE TEXT SEARCH CONFIGURATION ru (COPY = russian);

-- Настройка маппинга для русского языка
ALTER TEXT SEARCH CONFIGURATION ru
ALTER MAPPING FOR hword, hword_part, word
WITH russian_ispell, russian_stem;

-- Установка конфигурации поиска по умолчанию
ALTER SYSTEM SET default_text_search_config = 'ru';

-- Создание расширения pg_trgm для работы с текстом
CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- Добавление колонок для хранения tsvector
ALTER TABLE restaurants ADD COLUMN IF NOT EXISTS tsvector_column tsvector;
ALTER TABLE products ADD COLUMN IF NOT EXISTS tsvector_column tsvector;

-- Функция генерации tsvector для ресторанов
CREATE OR REPLACE FUNCTION make_restaurant_tsvector(name TEXT, description TEXT)
RETURNS tsvector AS
$$
BEGIN
    RETURN (
        setweight(to_tsvector('ru', coalesce(name, '')), 'A') ||
        setweight(to_tsvector('ru', coalesce(description, '')), 'B')
    );
END;
$$ LANGUAGE plpgsql IMMUTABLE;

-- Функция генерации tsvector для продуктов
CREATE OR REPLACE FUNCTION make_product_tsvector(name TEXT, category TEXT)
RETURNS tsvector AS
$$
BEGIN
    RETURN (
        setweight(to_tsvector('ru', coalesce(name, '')), 'A') ||
        setweight(to_tsvector('ru', coalesce(category, '')), 'B')
    );
END;
$$ LANGUAGE plpgsql IMMUTABLE;

UPDATE restaurants SET tsvector_column = make_restaurant_tsvector(name, description);
UPDATE products SET tsvector_column = make_product_tsvector(name, category);

CREATE OR REPLACE FUNCTION update_restaurant_tsvector() RETURNS trigger AS $$ 
BEGIN
    NEW.tsvector_column := make_restaurant_tsvector(NEW.name, NEW.description);
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Функция обновления tsvector для продуктов
CREATE OR REPLACE FUNCTION update_product_tsvector() RETURNS trigger AS $$ 
BEGIN
    NEW.tsvector_column := make_product_tsvector(NEW.name, NEW.category);
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Добавление триггеров для обновления tsvector
DROP TRIGGER IF EXISTS trg_update_restaurant_tsv ON restaurants;
CREATE TRIGGER trg_update_restaurant_tsv
BEFORE INSERT OR UPDATE ON restaurants
FOR EACH ROW EXECUTE FUNCTION update_restaurant_tsvector();

DROP TRIGGER IF EXISTS trg_update_product_tsv ON products;
CREATE TRIGGER trg_update_product_tsv
BEFORE INSERT OR UPDATE ON products
FOR EACH ROW EXECUTE FUNCTION update_product_tsvector();

-- Создание индексов для ускорения поиска
CREATE INDEX IF NOT EXISTS idx_restaurants_tsv ON restaurants USING GIN (tsvector_column);
CREATE INDEX IF NOT EXISTS idx_products_tsv ON products USING GIN (tsvector_column);



CREATE OR REPLACE FUNCTION issue_promocode_on_paid()
RETURNS TRIGGER AS $$
DECLARE
    new_promocode TEXT := 'PROMO_' || substr(md5(random()::text), 0, 8);
BEGIN
    IF NEW.status = 'paid' AND OLD.status IS DISTINCT FROM NEW.status THEN
        VALUES (
            new_promocode,
            0.10,
            NEW.user_id,
            now(),
            now() + INTERVAL '7 days'
        );
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;


CREATE TRIGGER trg_issue_promocode_on_paid
AFTER UPDATE ON orders
FOR EACH ROW
EXECUTE FUNCTION issue_promocode_on_paid();

